INSERT INTO feature VALUES('binders-in-scope','editor','Binders in scope at an offset','language-server','implemented','ordinary',NULL,'The lowering records each node''s reading frame as it resolves and keeps the frames of a declaration it refused, so the binders in scope at any offset are read off the narrowest reading holding it. Each written binder whose name an enclosing binder, an opened member, an earlier declaration, an import or a builtin already answers keeps the binding it hides, and the type table answers it at the binder.','surface-lowering surface-dispatcher','crates/surface-lowering/tests/scopes.rs crates/surface-lowering/tests/namespace.rs::a_shadowing_binder_hides_an_import_and_reaches_none_6270 crates/surface-dispatcher/src/typed.rs::each_shadowing_binder_of_the_own_text_is_kept_ascending_6270',NULL,NULL);
